class MyApp extends StatelessWidget{ const MyApp({super.key}); @override Widget build(BuildContext c){ return const MaterialApp(debugShowCheckedModeBanner: false, home: AuthGate()); } }
class AuthGate extends StatelessWidget{ const AuthGate({super.key}); @override Widget build(BuildContext context){ return StreamBuilder<User?>(stream: FirebaseAuth.instance.authStateChanges(), builder: (c,s){ if(s.connectionState==ConnectionState.waiting) return const Scaffold(body: Center(child: CircularProgressIndicator())); if(s.hasData) return const MedicinePage(); return const LoginPage(); }); } }
class LoginPage extends StatefulWidget{ const LoginPage({super.key}); @override State<LoginPage> createState()=> _LoginPageState(); }
class _LoginPageState extends State<LoginPage>{
final phoneCtrl=TextEditingController(text: "+919412341661"); final otpCtrl=TextEditingController(); String verId=""; bool otpSent=false; bool loading=false;
void sendOtp() async { setState(()=>loading=true); await FirebaseAuth.instance.verifyPhoneNumber(phoneNumber: phoneCtrl.text.trim(), verificationCompleted: (c){}, verificationFailed: (e){ ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.message??'Fail'))); setState(()=>loading=false); }, codeSent: (id,t){ setState((){ verId=id; otpSent=true; loading=false; }); ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('OTP Sent: 123456'))); }, codeAutoRetrievalTimeout: (id){ verId=id; }); }
void verifyOtp() async { setState(()=>loading=true); try{ final cred=PhoneAuthProvider.credential(verificationId: verId, smsCode: otpCtrl.text.trim()); await FirebaseAuth.instance.signInWithCredential(cred); }catch(e){ ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Wrong OTP'))); setState(()=>loading=false); } }
@override Widget build(BuildContext context){ return Scaffold(backgroundColor: Colors.deepPurple.shade50, body: Center(child: Card(margin: const EdgeInsets.all(20), shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)), child: Padding(padding: const EdgeInsets.all(24), child: Column(mainAxisSize: MainAxisSize.min, children: [const Icon(Icons.local_pharmacy, size: 60, color: Colors.deepPurple), const SizedBox(height: 10), const Text("Raj and Son's Medical Store", style: TextStyle(fontWeight: FontWeight.bold)), const Text("Hathras Junction, UP", style: TextStyle(fontSize: 12, color: Colors.grey)), const SizedBox(height: 20), TextField(controller: phoneCtrl, decoration: InputDecoration(labelText: "Mobile Number", border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)))), const SizedBox(height: 12), if(otpSent) TextField(controller: otpCtrl, decoration: InputDecoration(labelText: "OTP = 123456", border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)))), const SizedBox(height: 20), SizedBox(width: double.infinity, child: ElevatedButton(style: ElevatedButton.styleFrom(backgroundColor: Colors.deepPurple, foregroundColor: Colors.white), onPressed: loading? null : (otpSent? verifyOtp : sendOtp), child: Text(loading? "Wait..." : (otpSent? "Verify & Login" : "Send OTP")))), const Text("Test OTP: 123456", style: TextStyle(fontSize: 11))]))))); } }
class MedicinePage extends StatelessWidget{ const MedicinePage({super.key}); @override Widget build(BuildContext c){ return Scaffold(appBar: AppBar(backgroundColor: Colors.deepPurple, foregroundColor: Colors.white, title: const Text("Raj and Son's - Hathras Junction"), actions: [IconButton(onPressed: (){FirebaseAuth.instance.signOut();}, icon: const Icon(Icons.logout))]), body: StreamBuilder<QuerySnapshot>(stream: FirebaseFirestore.instance.collection('medicines').snapshots(), builder: (c,s){ if(!s.hasData) return const Center(child: CircularProgressIndicator()); final docs=s.data!.docs; return GridView.builder(padding: const EdgeInsets.all(12), gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount: 2, childAspectRatio: 0.7, crossAxisSpacing: 12, mainAxisSpacing: 12), itemCount: docs.length, itemBuilder: (c,i){ final d=docs[i].data() as Map<String,dynamic>; final name=(d['Name']??d['name']??'Medicine').toString(); final price=(d['Price']??d['price']??'₹0').toString(); return Card(child: Padding(padding: const EdgeInsets.all(10), child: Column(children: [Text(name, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 12), maxLines: 2, textAlign: TextAlign.center), const Spacer(), Text(price.contains('₹')?price:'₹$price', style: const TextStyle(color: Colors.deepPurple, fontWeight: FontWeight.bold))]))); }); })); } }
